import type { Metadata } from "next";
import { requireAdminSession } from "@/lib/server/auth/dal";
import { customerReports } from "@/lib/server/db/collections";
import { FileText, TrendingUp } from "lucide-react";

export const metadata: Metadata = { title: "Reports" };
export const dynamic = "force-dynamic";

/**
 * Customer reports list page.
 *
 * Displays the monthly usage reports generated by the `report.monthly` job
 * for this customer account. Each row shows the period, key metrics, and
 * AI-generated insights.
 */
export default async function AppReportsPage() {
  const session = await requireAdminSession();

  // Fetch all reports for this owner, newest first
  const col = await customerReports();
  const reports = await col
    .find({ ownerId: session.userId })
    .sort({ period: -1 })
    .limit(24) // up to 2 years back
    .toArray();

  return (
    <div className="space-y-6">
      <header className="space-y-1">
        <h1 className="text-2xl font-semibold tracking-tight">Reports</h1>
        <p className="text-muted-foreground max-w-2xl text-sm leading-relaxed">
          Monthly summaries of your usage, activity, and AI-generated insights.
          Reports are generated on the first of each month.
        </p>
      </header>

      {reports.length === 0 ? (
        <div className="border-border bg-muted/30 rounded-2xl border p-8 text-center">
          <FileText
            aria-hidden="true"
            className="text-muted-foreground mx-auto mb-3 size-8"
          />
          <p className="font-medium">No reports yet</p>
          <p className="text-muted-foreground mt-1 text-sm">
            Your first monthly report will appear here on the first day of next
            month, once your account has activity to summarise.
          </p>
        </div>
      ) : (
        <div className="space-y-4">
          {reports.map((report) => {
            const [year, month] = report.period.split("-");
            const date = new Date(Number(year), Number(month) - 1, 1);
            const periodLabel = date.toLocaleDateString("en-IN", {
              month: "long",
              year: "numeric",
            });

            // Pull a few key metrics for the summary line
            const metricEntries = Object.entries(report.metrics ?? {}).filter(
              ([, v]) => v > 0,
            );

            return (
              <article
                key={report.period}
                className="border-border bg-card rounded-2xl border p-5 shadow-[var(--shadow-soft)]"
              >
                <div className="flex items-start justify-between gap-4">
                  <div className="flex items-center gap-3">
                    <span className="bg-primary/10 text-primary flex size-9 shrink-0 items-center justify-center rounded-xl">
                      <TrendingUp aria-hidden="true" className="size-4.5" />
                    </span>
                    <div>
                      <h2 className="font-semibold">{periodLabel}</h2>
                      <p className="text-muted-foreground text-xs">
                        Generated{" "}
                        {report.createdAt.toLocaleDateString("en-IN", {
                          day: "numeric",
                          month: "short",
                          year: "numeric",
                        })}
                        {report.emailedAt && " · emailed"}
                      </p>
                    </div>
                  </div>

                  {/* Metric badges */}
                  {metricEntries.length > 0 && (
                    <div className="flex flex-wrap justify-end gap-2">
                      {metricEntries.slice(0, 4).map(([key, value]) => (
                        <span
                          key={key}
                          className="bg-muted text-muted-foreground rounded-lg px-2.5 py-1 text-xs font-medium capitalize"
                        >
                          {key.replace(/([A-Z])/g, " $1").toLowerCase()}:{" "}
                          <strong className="text-foreground">{value}</strong>
                        </span>
                      ))}
                    </div>
                  )}
                </div>

                {/* AI insights */}
                {report.insights && report.insights.length > 0 && (
                  <ul className="border-border mt-4 space-y-1.5 border-t pt-4">
                    {report.insights.map((insight, i) => (
                      <li
                        key={i}
                        className="text-muted-foreground flex items-start gap-2 text-sm"
                      >
                        <span
                          aria-hidden="true"
                          className="text-primary mt-0.5 shrink-0"
                        >
                          ·
                        </span>
                        {insight}
                      </li>
                    ))}
                  </ul>
                )}

                {/* All metrics */}
                {metricEntries.length > 0 && (
                  <div className="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">
                    {metricEntries.map(([key, value]) => (
                      <div
                        key={key}
                        className="bg-muted/40 rounded-lg p-3 text-center"
                      >
                        <p className="text-lg font-semibold tabular-nums">
                          {value.toLocaleString()}
                        </p>
                        <p className="text-muted-foreground mt-0.5 text-xs capitalize">
                          {key.replace(/([A-Z])/g, " $1").toLowerCase()}
                        </p>
                      </div>
                    ))}
                  </div>
                )}
              </article>
            );
          })}
        </div>
      )}
    </div>
  );
}
